def transform(g):
    out = [row[:] for row in g]
    n, m = len(g), len(g[0])
    for c, color in enumerate(g[0]):
        if color == 0:
            continue
        points = [(r, j) for r in range(1, n) for j in range(m) if g[r][j] == color]
        if not points:
            continue
        r, j = points[0]
        for rr in range(r + 1):
            out[rr][c] = color
        for cc in range(min(c, j), max(c, j) + 1):
            out[r][cc] = color
    return out
